Lemma rdn_some (M : word -> option byte) : forall (n : nat) a, 0 <= a -> a + Z.of_nat n <= 2 ^ 64 ->
  (forall i, 0 <= i < Z.of_nat n -> M (Z_to_bv 64 (a + i)) <> None) ->
  exists bs, rdn segs M (Z_to_bv 64 a) n = Some bs /\ length bs = n.
Proof.
